1	import { afterAll, beforeAll, describe, expect, it } from "vitest";
2	import { seaMap } from "@pirate-sea-race/content";
3	import { claimRules } from "@pirate-sea-race/content/claim";
4	import { intelRules } from "@pirate-sea-race/content/intel";
5	import { recordedOutcomes, startGameServer, type RunningGameServer } from "@pirate-sea-race/server";
6	import { sleep, type HeadlessClient, type ResultLineView } from "@pirate-sea-race/test-tools";
7	import { GUEST_SEAT, HOST_SEAT, lastDuel, placePair } from "./rubbingsSetup.js";
8	import { CLAIM_SEAT, collectFullSet, controlStartOf, flowTuning } from "./matchFlowSetup.js";
9	import { collectAt, dockFor, expectRoomChecks, grapple, HOLD_E, playersAt, resultOf, roomOf, tracker, until } from "./seaDuelSetup.js";
10	
11	/**
12	 * §2 and §12's endings through the real room, each with its exact results screen: a claim, the deadline (no winner),
13	 * a claim completing on the deadline tick (it wins), everyone leaving (abandoned) and a server fault (aborted, through
14	 * the room's test-only fault hook). Test-only timings: a two-second channel and a 20 s match.
15	 */
16	const CHANNEL = 40;
17	const MATCH_TICKS = 400;
18	let server: RunningGameServer;
19	let endpoint: string;
20	
21	beforeAll(async () => {
22	  // The minute-20 reveal falls due on the deadline tick: a match that has ended sends nothing more.
23	  const intel = { ...intelRules, sectorRevealTicks: MATCH_TICKS, carrierRevealTicks: MATCH_TICKS + 200 };
24	  const matchTuning = flowTuning({ claim: { ...claimRules, channelTicks: CHANNEL, deadlineTicks: MATCH_TICKS }, intel });
25	  server = await startGameServer({ port: 0, host: "127.0.0.1", handleSignals: false, testPlacement: true, matchTuning });
26	  endpoint = `http://127.0.0.1:${server.port}`;
27	});
28	
29	afterAll(async () => {
30	  await server.close();
31	});
32	
33	/** Old Stones' first dock: its sources are Suns in the test layout. */
34	const OLD_STONES = seaMap.docks.find((dock) => dock.island === 2)!;
35	
36	/** A results line with nothing accomplished: the starting gold, and `seat` and `winner`/`left` as given. */
37	const line = (seat: number, change: Partial<ResultLineView> = {}): ResultLineView => ({
38	  seat,
39	  winner: false,
40	  left: false,
41	  rubbingsHeld: 0,
42	  collected: 0,
43	  thefts: 0,
44	  lost: 0,
45	  duelsWon: 0,
46	  duelsLost: 0,
47	  duelsDrawn: 0,
48	  gold: 50,
49	  cachesClaimed: 0,
50	  islandsVisited: 0,
51	  ...change,
52	});
53	
54	/** Both players' results screens, once both show one; they are the same. */
55	async function resultsOf(host: HeadlessClient, guest: HeadlessClient, timeoutMs = 25_000) {
56	  for (const client of [host, guest]) await client.waitFor(() => client.results() !== undefined, timeoutMs);
57	  expect(guest.results()).toEqual(host.results());
58	  for (const client of [host, guest]) expect(client.phase).toBe("ended");
59	  return host.results()!;
60	}
61	
62	describe.concurrent("the endings (§2, §12)", () => {
63	  it("ends by a claim: the winner first, and every player's accomplishments", async ({ onTestFinished }) => {
64	    const track = tracker(onTestFinished);
65	    const [host, guest] = (await playersAt(endpoint, [HOST_SEAT, GUEST_SEAT], track)) as [HeadlessClient, HeadlessClient];
66	    await collectAt(guest, endpoint, OLD_STONES, "sun");
67	    await collectFullSet(host, endpoint);
68	    await host.placeShip(endpoint, CLAIM_SEAT);
69	    await host.holdUntil(HOLD_E, () => host.results() !== undefined, 8000);
70	    const results = await resultsOf(host, guest);
71	    const controlStart = controlStartOf(host);
72	    expect(results).toMatchObject({ reason: "claim", winnerSeat: host.seat });
73	    expect(results.elapsedTicks).toBe(results.tick - controlStart);
74	    expect(results.players).toEqual([
75	      line(host.seat, { winner: true, rubbingsHeld: 2, collected: 2, islandsVisited: 2 }),
76	      line(guest.seat, { rubbingsHeld: 1, collected: 1, islandsVisited: 1 }),
77	    ]);
78	  }, 30_000);
79	
80	  it("ends at the deadline with no winner, counting a duel, its theft and its gold", async ({ onTestFinished }) => {
81	    const track = tracker(onTestFinished);
82	    // The guest never readies its arena: it forfeits the duel.
83	    const [host, guest] = (await playersAt(endpoint, [HOST_SEAT, GUEST_SEAT], track, { clients: [{}, { autoReady: false }] })) as [HeadlessClient, HeadlessClient];
84	    await collectAt(host, endpoint, dockFor("sun"), "sun");
85	    await collectAt(guest, endpoint, dockFor("moon"), "moon");
86	    await placePair(endpoint, host, guest);
87	    await grapple(host, guest);
88	    await host.waitFor(() => host.objectives()!.theftOptions.join(",") === "moon", 10_000);
89	    host.chooseTheft("moon");
90	    await host.waitFor(() => host.rubbings().join(",") === "sun,moon");
91	    // The loser respawns moored at a dock: that island counts as visited too.
92	    await guest.waitFor(() => guest.status()?.mode === "sea" && guest.ship()!.dock >= 0, 10_000);
93	    const guestIslands = new Set([dockFor("moon").island, seaMap.docks[guest.ship()!.dock]!.island]).size;
94	    const results = await resultsOf(host, guest);
95	    expect(results).toMatchObject({ reason: "deadline", winnerSeat: 0, tick: controlStartOf(host) + MATCH_TICKS, elapsedTicks: MATCH_TICKS });
96	    for (const client of [host, guest]) expect(client.reveals.filter((reveal) => reveal.kind === "sector-reveal")).toEqual([]);
97	    expect(results.players).toEqual([
98	      line(host.seat, { rubbingsHeld: 2, collected: 1, thefts: 1, duelsWon: 1, gold: 60, islandsVisited: 1 }),
99	      line(guest.seat, { rubbingsHeld: 0, collected: 1, lost: 1, duelsLost: 1, gold: 40, islandsVisited: guestIslands }),
100	    ]);
101	  }, 35_000);
102	
103	  it("lets a claim completing on the deadline tick win", async ({ onTestFinished }) => {
104	    const track = tracker(onTestFinished);
105	    const [host, guest] = (await playersAt(endpoint, [HOST_SEAT, GUEST_SEAT], track)) as [HeadlessClient, HeadlessClient];
106	    await collectFullSet(host, endpoint);
107	    await host.placeShip(endpoint, CLAIM_SEAT);
108	    const room = roomOf(host);
109	    const deadline = controlStartOf(host) + MATCH_TICKS;
110	    expect(room.claimConfiguration!.deadlineTick).toBe(deadline);
111	    // The clock stops after the tick before the channel's start that completes it on the deadline tick; E goes
112	    // down while it is stopped, so the channel starts on the next tick.
113	    room.pauseAfterTick(deadline - CHANNEL - 1);
114	    await until(() => room.worldPaused, 20_000, "the pause");
115	    const stopped = room.matchState.worldTick;
116	    expect(stopped).toBe(deadline - CHANNEL - 1);
117	    const holding = host.holdUntil(HOLD_E, () => host.results() !== undefined, 8000);
118	    await sleep(250);
119	    // Stopped: no world tick ran meanwhile.
120	    expect(room.matchState.worldTick).toBe(stopped);
121	    room.resumeWorld();
122	    await holding;
123	    const results = await resultsOf(host, guest);
124	    expect(room.claimState!.result).toEqual({ reason: "claim", winner: host.sessionId, tick: deadline });
125	    expect(results).toMatchObject({ reason: "claim", winnerSeat: host.seat, tick: deadline, elapsedTicks: MATCH_TICKS });
126	    expect(results.players[0]).toEqual(line(host.seat, { winner: true, rubbingsHeld: 2, collected: 2, islandsVisited: 2 }));
127	  }, 35_000);
128	
129	  it("ends abandoned, with no winner, when everyone leaves after the start", async ({ onTestFinished }) => {
130	    const track = tracker(onTestFinished);
131	    const [host, guest] = (await playersAt(endpoint, [HOST_SEAT, GUEST_SEAT], track)) as [HeadlessClient, HeadlessClient];
132	    const code = host.code;
133	    const room = roomOf(host);
134	    await collectAt(host, endpoint, dockFor("sun"), "sun");
135	    const seats = [host.seat, guest.seat];
136	    await Promise.all([host.leave(), guest.leave()]);
137	    await until(() => recordedOutcomes().some((outcome) => outcome.code === code), 5000, "the recorded outcome");
138	    const results = recordedOutcomes().find((outcome) => outcome.code === code)!.results;
139	    expect(results).toMatchObject({ reason: "abandoned", winner: null, custom: true });
140	    // Neither holds a rubbing at the end, so the lines are in id order; compared here by seat.
141	    const bySeat = results.players.map(({ id, ...rest }) => ({ ...rest, seat: room.seatOf(id) })).sort((a, b) => a.seat - b.seat);
142	    expect(bySeat).toEqual([
143	      // The host's Sun went into a cache when it quit: collected, then lost.
144	      line(seats[0]!, { left: true, collected: 1, lost: 1, islandsVisited: 1 }),
145	      line(seats[1]!, { left: true }),
146	    ]);
147	    expectRoomChecks(room);
148	  });
149	
150	  it("counts a cancelled duel for neither fighter (neither readied its arena)", async ({ onTestFinished }) => {
151	    const track = tracker(onTestFinished);
152	    const [host, guest] = (await playersAt(endpoint, [HOST_SEAT, GUEST_SEAT], track, { clients: [{ autoReady: false }, { autoReady: false }] })) as [HeadlessClient, HeadlessClient];
153	    await grapple(host, guest);
154	    await until(() => lastDuel(host)?.phase === "settled", 8000, "the cancellation");
155	    expect(lastDuel(host)).toMatchObject({ result: { outcome: "cancelled" } });
156	    for (const client of [host, guest]) await client.waitFor(() => client.status()?.mode === "sea", 3000);
157	    roomOf(host).injectFault();
158	    const results = await resultsOf(host, guest, 5000);
159	    expect(results).toMatchObject({ reason: "aborted", winnerSeat: 0 });
160	    // Nobody holds a rubbing, so the lines are in id order: compared here by seat.
161	    expect([...results.players].sort((a, b) => a.seat - b.seat)).toEqual([line(host.seat), line(guest.seat)].sort((a, b) => a.seat - b.seat));
162	  }, 20_000);
163	
164	  it("cancels a duel still being fought when the match ends, and counts it for neither fighter", async ({ onTestFinished }) => {
165	    const track = tracker(onTestFinished);
166	    const [host, guest] = (await playersAt(endpoint, [HOST_SEAT, GUEST_SEAT], track)) as [HeadlessClient, HeadlessClient];
167	    await grapple(host, guest);
168	    for (const client of [host, guest]) await client.waitFor(() => client.fighter.phase === "fighting", 8000);
169	    roomOf(host).injectFault();
170	    const results = await resultsOf(host, guest, 5000);
171	    expect(results).toMatchObject({ reason: "aborted", winnerSeat: 0 });
172	    expect([...results.players].sort((a, b) => a.seat - b.seat)).toEqual([line(host.seat), line(guest.seat)].sort((a, b) => a.seat - b.seat));
173	    // Outcomes freeze: the ledger cancels the fight (nothing moves), and both fighters see it end, cancelled.
174	    expect(lastDuel(host)).toMatchObject({ phase: "settled", result: { outcome: "cancelled" }, settlement: { choice: "none", gold: 0 } });
175	    expect(await resultOf(host, guest, 3000)).toEqual({ phase: "over", winner: -1, reason: "cancelled" });
176	    // The cancelled duel is shown for a moment, then leaves both views: back to the sea and its results screen.
177	    for (const client of [host, guest]) await client.waitFor(() => client.duelCount === 0, 5000);
178	  }, 20_000);
179	
180	  it("keeps running while a quitter's rubbing waits in the winner's theft window, and counts the forfeit and the theft", async ({ onTestFinished }) => {
181	    const track = tracker(onTestFinished);
182	    const [host, guest] = (await playersAt(endpoint, [HOST_SEAT, GUEST_SEAT], track)) as [HeadlessClient, HeadlessClient];
183	    await collectAt(guest, endpoint, dockFor("moon"), "moon");
184	    await placePair(endpoint, host, guest);
185	    await grapple(host, guest);
186	    await host.waitFor(() => host.fighter.phase === "fighting", 8000);
187	    const room = roomOf(host);
188	    const seats = [host.seat, guest.seat];
189	    // The guest quits mid-fight: a forfeit, its Moon held for the host's choice while its ship is gone.
190	    await guest.leave();
191	    await host.waitFor(() => host.objectives()?.theftOptions.join(",") === "moon", 5000);
192	    expect(room.ledgerState.rubbings.filter((rubbing) => rubbing.location.kind === "duel")).toHaveLength(1);
193	    await sleep(300);
