1	import { afterAll, beforeAll, describe, expect, it } from "vitest";
2	import { seaMap } from "@pirate-sea-race/content";
3	import { dockCentre, startGameServer, type RunningGameServer } from "@pirate-sea-race/server";
4	import { createEncounterConfig } from "@pirate-sea-race/simulation/encounters";
5	import { cacheRubbings, objectiveRules } from "@pirate-sea-race/simulation/objectives";
6	import { ImpairmentProxy, sleep, type HeadlessClient } from "@pirate-sea-race/test-tools";
7	import { GUEST_SEAT, holds, HOST_SEAT, lastDuel, ledgerOf, ledgerPlayer, pair, placePair, QUICK_ABSENCE_TICKS, quickEncounters, tuned } from "./rubbingsSetup.js";
8	import { collectAt, dockFor, grapple, playersAt, roomOf, tracker, until } from "./seaDuelSetup.js";
9	
10	/**
11	 * §12's timers on the world tick, with a short seat (test-only override: 10 s instead of 60 s; one-second holds; a 3 s
12	 * duel absence): a reservation that expires removes the player and leaves exactly their remaining rubbings in a cache
13	 * at the dock the encounter rules would respawn them at; a disconnected ship can be grappled and robbed; a fighter who
14	 * drops mid-duel forfeits after the absence counted in world ticks, respawns, and keeps the seat to its deadline.
15	 * Every test's rooms check the ledger and the room invariants after every world tick (`tracker`).
16	 */
17	const SEAT_TICKS = 200;
18	let server: RunningGameServer;
19	let endpoint: string;
20	const encounters = createEncounterConfig({ rules: quickEncounters });
21	
22	beforeAll(async () => {
23	  server = await startGameServer({
24	    port: 0,
25	    host: "127.0.0.1",
26	    handleSignals: false,
27	    testPlacement: true,
28	    matchTuning: tuned({ objectives: { ...objectiveRules, collectTicks: 20, cacheClaimTicks: 20, seatReservationTicks: SEAT_TICKS }, reconnectionSeconds: 15 }),
29	  });
30	  endpoint = `http://127.0.0.1:${server.port}`;
31	});
32	
33	afterAll(async () => {
34	  await server.close();
35	});
36	
37	describe.concurrent("the seat's reservation on the world tick (§12)", () => {
38	  it("removes a player whose reservation expires, with exactly their rubbings in a cache at the dock the rules would respawn them at", async ({ onTestFinished }) => {
39	    const track = tracker(onTestFinished);
40	    const proxy = await ImpairmentProxy.start(server.port);
41	    onTestFinished(async () => void (await proxy.close()));
42	    // The leaver sails out of Mist Cay's north; a watcher sits in its sight.
43	    const [watcher, leaver] = (await playersAt(endpoint, [HOST_SEAT, GUEST_SEAT], track, { endpoints: [endpoint, proxy.endpoint] })) as [HeadlessClient, HeadlessClient];
44	    await collectAt(leaver, endpoint, dockFor("sun"), "sun");
45	    await collectAt(leaver, endpoint, dockFor("moon"), "moon");
46	    await placePair(endpoint, watcher, leaver);
47	    proxy.sever({ refuse: true });
48	    await until(() => ledgerPlayer(watcher, leaver.sessionId)?.status === "disconnected", 3000, "the disconnect");
49	    const deadline = ledgerPlayer(watcher, leaver.sessionId)!.reservationDeadline!;
50	    const ship = roomOf(watcher).matchState.ships.find((each) => each.id === leaver.sessionId)!;
51	    // The ship stays in the world (and in the watcher's sight) until the deadline.
52	    await sleep(1000);
53	    expect(watcher.ship(leaver.sessionId)).toBeDefined();
54	    await until(() => ledgerPlayer(watcher, leaver.sessionId)?.status === "left", 15_000, "the expiry");
55	    const ledger = ledgerOf(watcher);
56	    expect(ledger.caches).toHaveLength(1);
57	    const [cache] = ledger.caches;
58	    expect(cache!.createdTick).toBe(deadline);
59	    const expected = encounters.modes.ship.rules.respawnPoint({ encounter: ship, own: ship, opponents: [watcher.ship()!], clearRadius: encounters.respawnClearRadius });
60	    expect({ x: cache!.x, y: cache!.y }).toEqual({ x: expected.x, y: expected.y });
61	    expect(cacheRubbings(ledger, cache!.id).map((rubbing) => rubbing.type).sort()).toEqual(["moon", "sun"]);
62	    await watcher.waitFor(() => watcher.ship(leaver.sessionId) === undefined && watcher.playerCount === 1, 2000);
63	    expect(roomOf(watcher).matchState.ships.map((each) => each.id)).toEqual([watcher.sessionId]);
64	    // §12: the released seat counts as leaving the match: the flow and its roster drop the player.
65	    await watcher.waitFor(() => watcher.room.state.roster.size === 1, 2000);
66	    expect([...watcher.room.state.roster.values()].map((entry) => entry.seat)).toEqual([watcher.seat]);
67	    expect(roomOf(watcher).flowState.players.find((player) => player.id === leaver.sessionId)?.left).toBe(true);
68	  }, 45_000);
69	
70	  it("lets a disconnected ship be grappled and robbed, and drops its seat at the deadline", async ({ onTestFinished }) => {
71	    const track = tracker(onTestFinished);
72	    const proxy = await ImpairmentProxy.start(server.port);
73	    onTestFinished(async () => void (await proxy.close()));
74	    const { host, guest } = await pair(endpoint, track, {}, [endpoint, proxy.endpoint]);
75	    await collectAt(guest, endpoint, dockFor("moon"), "moon");
76	    await placePair(endpoint, host, guest);
77	    proxy.sever({ refuse: true });
78	    await until(() => ledgerPlayer(host, guest.sessionId)?.status === "disconnected", 3000, "the disconnect");
79	    // The ship is still there, in sight and grapple range: the host grapples it; the absent guest forfeits.
80	    expect(host.ship(guest.sessionId)).toBeDefined();
81	    host.tapGrapple();
82	    await host.waitFor(() => host.objectives()?.theftOptions.join(",") === "moon", 8000);
83	    host.chooseTheft("moon");
84	    await host.waitFor(() => host.rubbings().join(",") === "moon" && host.gold() === 60, 2000);
85	    expect(ledgerPlayer(host, guest.sessionId)).toMatchObject({ status: "disconnected", gold: 40 });
86	    expect(holds(host, guest.sessionId)).toEqual([]);
87	    // Never back: at the deadline the seat goes, with nothing left for a cache.
88	    await until(() => ledgerPlayer(host, guest.sessionId)?.status === "left", 15_000, "the expiry");
89	    expect(ledgerOf(host).caches).toEqual([]);
90	  }, 45_000);
91	
92	  it("forfeits a fighter away from the duel for its absence in world ticks; they respawn, keep the seat to its deadline, then their rest goes to a cache", async ({ onTestFinished }) => {
93	    const track = tracker(onTestFinished);
94	    const proxy = await ImpairmentProxy.start(server.port);
95	    onTestFinished(async () => void (await proxy.close()));
96	    const { host, guest } = await pair(endpoint, track, {}, [endpoint, proxy.endpoint]);
97	    await collectAt(guest, endpoint, dockFor("sun"), "sun");
98	    await collectAt(guest, endpoint, dockFor("moon"), "moon");
99	    await placePair(endpoint, host, guest);
100	    await grapple(host, guest);
101	    await host.waitFor(() => host.fighter.phase === "fighting", 5000);
102	    proxy.sever({ refuse: true });
103	    await until(() => ledgerPlayer(host, guest.sessionId)?.status === "disconnected", 3000, "the drop");
104	    const deadline = ledgerPlayer(host, guest.sessionId)!.reservationDeadline!;
105	    const dropTick = deadline - SEAT_TICKS;
106	    await host.waitFor(() => (host.objectives()?.theftOptions.length ?? 0) === 2, 8000);
107	    // The forfeit came from the room's count of world ticks, not a socket timer.
108	    const forfeitTick = lastDuel(host)!.result!.tick;
109	    expect(forfeitTick - dropTick).toBeGreaterThanOrEqual(QUICK_ABSENCE_TICKS);
110	    expect(forfeitTick - dropTick).toBeLessThanOrEqual(QUICK_ABSENCE_TICKS + 2);
111	    host.chooseTheft("sun");
112	    await host.waitFor(() => host.rubbings().join(",") === "sun", 2000);
113	    // The loser respawns at a dock, still disconnected, still holding the Moon, until the seat's deadline.
114	    await until(() => roomOf(host).matchState.ships.find((ship) => ship.id === guest.sessionId)?.dock !== -1 && roomOf(host).encounterState.players.every((player) => player.respawn === null), 8000, "the respawn");
115	    const respawnDock = roomOf(host).matchState.ships.find((ship) => ship.id === guest.sessionId)!.dock;
116	    expect(ledgerPlayer(host, guest.sessionId)).toMatchObject({ status: "disconnected", reservationDeadline: deadline });
117	    expect(holds(host, guest.sessionId)).toEqual(["moon"]);
118	    await until(() => ledgerPlayer(host, guest.sessionId)?.status === "left", 15_000, "the expiry");
119	    const ledger = ledgerOf(host);
120	    expect(ledger.caches).toHaveLength(1);
121	    expect(ledger.caches[0]).toMatchObject({ createdTick: deadline, ...dockCentre(seaMap, respawnDock) });
122	    expect(cacheRubbings(ledger, ledger.caches[0]!.id).map((rubbing) => rubbing.type)).toEqual(["moon"]);
123	  }, 45_000);
124	});
